# Forgetting __eq__ leads to identity comparison

class Player:
    def __init__(self, name):
        self.name = name

player1 = Player("Aragorn")
player2 = Player("Aragorn")

# Without __eq__, compares identity (memory address)
print(f"player1 == player2: {player1 == player2}")
print(f"player1 is player2: {player1 is player2}")

# This works with __eq__ defined!
class PlayerWithEq:
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        if not isinstance(other, PlayerWithEq):
            return False
        return self.name == other.name

p1 = PlayerWithEq("Aragorn")
p2 = PlayerWithEq("Aragorn")
print(f"p1 == p2: {p1 == p2}")
